<template>
  <AppLoader title="Opening" />
</template>

<script setup lang="ts">
import { resolveSmsShortLink } from '~/client';

definePageMeta({
  layout: 'share',
  auth: false,
  // nav-journey records every afterEach, so without this GoBackButton on the landing page would target
  // this route, which would resolve again and forward straight back - an inescapable loop.
  skipNavJourney: true,
});

const route = useRoute('r-code');
const router = useRouter();

// On the web this path never reaches a page: a Nitro server route answers it and redirects before the app
// boots. A native build ships no server, so the same code-to-target resolve has to happen here. It cannot
// move into the deep-link plugin that receives the tapped URL, because the generated client's baseURL is
// only configured once app.vue mounts - a plugin-time call would have no API host at all.
onMounted(async () => {
  let path: string | null = null;
  try {
    const { target_url } = await resolveSmsShortLink({
      composable: '$fetch',
      path: { code: route.params.code },
      // a hung backend must not leave the recipient watching a spinner with no way out
      timeout: 5000,
    });
    path = routePathFromUrl(target_url);
  } catch (error) {
    console.error(`[SmsRedirect] Failed to resolve code ${route.params.code}:`, error);
  }
  // an unresolvable code, a network failure, or a target this bundle has no page for all land on the public
  // recruitment page - the text message's call to action must never dead-end
  const target = path !== null && router.resolve(path).matched.length > 0 ? path : '/join';
  await router.replace(target);
});
</script>
